#!/usr/bin/env node

import { execSync } from "child_process";

const args = process.argv.slice(2);

if (args.length === 0 || args[0] === "--help") {
	console.log("Usage: chrome-dialog.js --accept [text]");
	console.log("       chrome-dialog.js --dismiss");
	console.log("\nHandle browser dialogs (alert, confirm, prompt).");
	console.log("\nOptions:");
	console.log("  --accept [text]   Accept dialog, optionally with prompt text");
	console.log("  --dismiss         Dismiss/cancel dialog");
	console.log("\nExamples:");
	console.log("  chrome-dialog.js --accept");
	console.log('  chrome-dialog.js --accept "My input text"');
	console.log("  chrome-dialog.js --dismiss");
	process.exit(0);
}

const MCP_CMD = "npx -y @anthropic-ai/chrome-devtools-mcp@latest";
const SERVER = "chrome-devtools";

function callMcp(tool, params = {}) {
	const paramStr = Object.entries(params)
		.map(([k, v]) => `${k}:${JSON.stringify(v)}`)
		.join(" ");

	const cmd = `npx mcporter call --stdio "${MCP_CMD}" ${SERVER}.${tool} ${paramStr}`;

	try {
		return execSync(cmd, { encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
	} catch (error) {
		throw new Error(error.stderr || error.message);
	}
}

// Parse arguments
let action = "";
let promptText = "";

for (let i = 0; i < args.length; i++) {
	const arg = args[i];

	if (arg === "--accept") {
		action = "accept";
		const next = args[i + 1];
		if (next && !next.startsWith("--")) {
			promptText = args[++i];
		}
	} else if (arg === "--dismiss") {
		action = "dismiss";
	}
}

if (!action) {
	console.error("Error: Specify --accept or --dismiss");
	process.exit(1);
}

try {
	const params = { action };
	if (promptText) {
		params.promptText = promptText;
	}

	callMcp("handle_dialog", params);
	console.log(`Dialog ${action}ed${promptText ? ` with: "${promptText}"` : ""}`);
} catch (error) {
	console.error("Error:", error.message);
	process.exit(1);
}

