	console.log('  chrome-fill.js "country-select" "United States"');
	console.log('  chrome-fill.js --form \'[{"uid":"email","value":"a@b.com"},{"uid":"pass","value":"secret"}]\'');
	process.exit(0);
}

const MCP_CMD = "npx -y @anthropic-ai/chrome-devtools-mcp@latest";
