		.map(([k, v]) => `${k}:${JSON.stringify(v)}`)
		.join(" ");

	const cmd = `npx mcporter call --stdio "${MCP_CMD}" ${SERVER}.${tool} ${paramStr}`;

	try {
		return execSync(cmd, { encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
	} catch (error) {
		throw new Error(error.stderr || error.message);
	}
}

// Parse arguments
let uid = "";
let value = "";
let formJson = "";

for (let i = 0; i < args.length; i++) {
	const arg = args[i];

	if (arg === "--form") {
		formJson = args[++i];
	} else if (!arg.startsWith("--")) {
		if (!uid) {
			uid = arg;
		} else if (!value) {
			value = arg;
		}
	}
}

try {
	if (formJson) {
		const elements = JSON.parse(formJson);
		callMcp("fill_form", { elements });
		console.log(`Filled ${elements.length} form field(s)`);
		elements.forEach((el, i) => {
			console.log(`  ${i + 1}. ${el.uid}: "${el.value}"`);
		});
