			console.error("Error: Both <uid> and <value> required");
			console.error("Usage: chrome-fill.js <uid> <value>");
			process.exit(1);
		}

		callMcp("fill", { uid, value });
		console.log(`Filled "${uid}" with: "${value}"`);
	}
} catch (error) {
	console.error("Error:", error.message);
	process.exit(1);
