		return execSync(cmd, { encoding: "utf-8", stdio: ["pipe", "pipe", "pipe"] });
	} catch (error) {
		throw new Error(error.stderr || error.message);
	}
}

// Parse arguments
const options = {};

for (let i = 0; i < args.length; i++) {
	const arg = args[i];

