	} catch (error) {
		throw new Error(error.stderr || error.message);
	}
}

// Parse arguments
let direction = "";
let amount = 500;
let toUid = "";
let instant = false;

for (let i = 0; i < args.length; i++) {
	const arg = args[i];

	if (arg === "--to") {
		toUid = args[++i];
	} else if (arg === "--instant") {
		instant = true;
	} else if (!arg.startsWith("--")) {
		if (!direction) {
			direction = arg.toLowerCase();
		} else {
			amount = parseInt(arg) || 500;
		}
	}
}

// Build JavaScript function based on action
let jsFunction = "";
let description = "";

if (toUid) {
	// Scroll element into view
	const behavior = instant ? "instant" : "smooth";
	jsFunction = `(el) => { el.scrollIntoView({ behavior: "${behavior}", block: "center" }); return "scrolled"; }`;
	description = `Scrolled to element: ${toUid}`;
} else {
	switch (direction) {
		case "down":
			jsFunction = `() => { window.scrollBy({ top: ${amount}, behavior: "smooth" }); return window.scrollY; }`;
			description = `Scrolled down ${amount}px`;
			break;

		case "up":
			jsFunction = `() => { window.scrollBy({ top: -${amount}, behavior: "smooth" }); return window.scrollY; }`;
			description = `Scrolled up ${amount}px`;
			break;

		case "top":
			jsFunction = `() => { window.scrollTo({ top: 0, behavior: "smooth" }); return "top"; }`;
			description = "Scrolled to top";
			break;

		case "bottom":
			jsFunction = `() => { window.scrollTo({ top: document.body.scrollHeight, behavior: "smooth" }); return "bottom"; }`;
			description = "Scrolled to bottom";
			break;

		case "page-down":
			jsFunction = `() => { window.scrollBy({ top: window.innerHeight * 0.9, behavior: "smooth" }); return window.scrollY; }`;
			description = "Scrolled down one page";
			break;

		case "page-up":
			jsFunction = `() => { window.scrollBy({ top: -window.innerHeight * 0.9, behavior: "smooth" }); return window.scrollY; }`;
			description = "Scrolled up one page";
			break;

		default:
			console.error(`Error: Unknown direction "${direction}"`);
			console.error("Valid: down, up, top, bottom, page-down, page-up");
			process.exit(1);
	}
}

try {
	const params = { function: jsFunction };

	if (toUid) {
		params.args = [{ uid: toUid }];
	}

	callMcp("evaluate_script", params);
	console.log(description);
} catch (error) {
	console.error("Error:", error.message);
	process.exit(1);
}

