#!/usr/bin/env node

import sharp from "sharp";
import { existsSync, mkdirSync } from "fs";
import { dirname, basename, extname, join } from "path";

const args = process.argv.slice(2);

if (args.length === 0 || args[0] === "--help") {
	console.log("Usage: chrome-split-image.js <input-image> [options]");
	console.log("\nSplit a large screenshot into sections for viewing.");
	console.log("Useful for full-page screenshots that exceed API size limits.");
	console.log("\nOptions:");
	console.log("  --max-height N   Max height per section in pixels (default: 7500)");
	console.log("  --output DIR     Output directory (default: same as input)");
	console.log("  --info           Just show image dimensions, don't split");
	console.log("\nExamples:");
	console.log("  chrome-split-image.js /tmp/full-page.png");
	console.log("  chrome-split-image.js /tmp/full-page.png --max-height 5000");
	console.log("  chrome-split-image.js /tmp/full-page.png --output /tmp/sections");
	console.log("  chrome-split-image.js /tmp/full-page.png --info");
	console.log("\nOutput:");
	console.log("  Creates files like: full-page-1.png, full-page-2.png, etc.");
	console.log("  Returns list of created files for the agent to read.");
	process.exit(0);
}

// Parse arguments
let inputFile = null;
let maxHeight = 7500; // Safe margin under 8000px API limit
let outputDir = null;
let infoOnly = false;

for (let i = 0; i < args.length; i++) {
	const arg = args[i];

	if (arg === "--max-height") {
		maxHeight = parseInt(args[++i]) || 7500;
	} else if (arg === "--output") {
		outputDir = args[++i];
	} else if (arg === "--info") {
		infoOnly = true;
	} else if (!arg.startsWith("--")) {
		inputFile = arg;
	}
}

if (!inputFile) {
	console.error("Error: No input file specified");
	process.exit(1);
}

if (!existsSync(inputFile)) {
	console.error(`Error: File not found: ${inputFile}`);
	process.exit(1);
}

async function main() {
	try {
		const image = sharp(inputFile);
		const metadata = await image.metadata();
		const { width, height, format } = metadata;

		console.log(`Image: ${inputFile}`);
		console.log(`Dimensions: ${width}x${height}`);
		console.log(`Format: ${format}`);

		if (infoOnly) {
			if (height > 8000) {
				console.log(`\nWARNING: Height ${height}px exceeds 8000px API limit.`);
				console.log(`Sections needed: ${Math.ceil(height / maxHeight)}`);
			} else {
				console.log(`\nImage is within API limits (< 8000px).`);
			}
			return;
		}

		// Check if splitting is needed
		if (height <= maxHeight) {
			console.log(`\nNo splitting needed - image height (${height}px) is within limit (${maxHeight}px).`);
			console.log(`\nFiles to view:`);
			console.log(`  ${inputFile}`);
			return;
		}

		// Calculate sections
		const numSections = Math.ceil(height / maxHeight);
		console.log(`\nSplitting into ${numSections} sections (max ${maxHeight}px each)...`);

		// Setup output
		const inputDir = dirname(inputFile);
		const inputName = basename(inputFile, extname(inputFile));
		const inputExt = extname(inputFile);
		const outDir = outputDir || inputDir;

		if (outputDir && !existsSync(outputDir)) {
			mkdirSync(outputDir, { recursive: true });
		}

		const createdFiles = [];

		for (let i = 0; i < numSections; i++) {
			const top = i * maxHeight;
			const sectionHeight = Math.min(maxHeight, height - top);
			const outputFile = join(outDir, `${inputName}-${i + 1}${inputExt}`);

			await sharp(inputFile)
				.extract({ left: 0, top, width, height: sectionHeight })
				.toFile(outputFile);

			createdFiles.push(outputFile);
			console.log(`  Created: ${outputFile} (${width}x${sectionHeight})`);
		}

		console.log(`\nFiles to view (in order):`);
		createdFiles.forEach((f, i) => {
			console.log(`  ${i + 1}. ${f}`);
		});

	} catch (error) {
		console.error("Error:", error.message);
		process.exit(1);
	}
}

main();
